#!/usr/bin/env python3
"""Validate files generated by generate_graded_hex_mesh.py."""

from __future__ import annotations

import argparse
import json
import math
import sys
from pathlib import Path
from typing import Sequence


def _fail(message: str) -> None:
    raise ValueError(message)


def _read_mesh(path: Path):
    coordinates: list[tuple[float, float, float]] = []
    cells: list[tuple[int, ...]] = []
    with path.open("r", encoding="utf-8") as stream:
        data_lines = [
            line.strip()
            for line in stream
            if line.strip() and not line.lstrip().startswith(("!", "#"))
        ]
    if not data_lines:
        _fail("mesh file is empty")

    header = data_lines[0].split()
    if len(header) != 2:
        _fail("mesh header must contain node and cell counts")
    nnodes, ncells = (int(value) for value in header)
    if nnodes <= 0 or ncells <= 0:
        _fail("mesh counts must be positive")
    if len(data_lines) != 1 + nnodes + ncells:
        _fail(
            f"mesh line count mismatch: expected {1 + nnodes + ncells}, "
            f"found {len(data_lines)}"
        )

    for line in data_lines[1 : 1 + nnodes]:
        values = tuple(float(value) for value in line.split())
        if len(values) != 3:
            _fail("node line must contain three coordinates")
        coordinates.append(values)  # type: ignore[arg-type]

    for line in data_lines[1 + nnodes :]:
        values = tuple(int(value) for value in line.split())
        if len(values) != 8:
            _fail("Hex8 cell line must contain eight node IDs")
        cells.append(values)
    return coordinates, cells


def _check_cells(
    coordinates: Sequence[tuple[float, float, float]],
    cells: Sequence[tuple[int, ...]],
    tolerance: float,
) -> None:
    for cell_id, cell in enumerate(cells):
        if any(node < 0 or node >= len(coordinates) for node in cell):
            _fail(f"cell {cell_id} references an invalid node")

        n0, n1, n2, n3, n4, n5, n6, n7 = (
            coordinates[node] for node in cell
        )
        if not (
            n0[0] < n1[0]
            and n0[1] < n3[1]
            and n0[2] < n4[2]
        ):
            _fail(f"cell {cell_id} has invalid Hex8 node ordering")

        x0, y0, z0 = n0
        x1, y1, z1 = n1[0], n3[1], n4[2]
        expected = (
            (x0, y0, z0),
            (x1, y0, z0),
            (x1, y1, z0),
            (x0, y1, z0),
            (x0, y0, z1),
            (x1, y0, z1),
            (x1, y1, z1),
            (x0, y1, z1),
        )
        actual = (n0, n1, n2, n3, n4, n5, n6, n7)
        if any(
            abs(actual_value[axis] - expected_value[axis]) > tolerance
            for actual_value, expected_value in zip(actual, expected)
            for axis in range(3)
        ):
            _fail(f"cell {cell_id} is not an orthorhombic Hex8")


def validate(output_dir: Path, tolerance: float) -> dict[str, int]:
    mesh_path = output_dir / "mesh-3d.txt"
    particles_path = output_dir / "particles-3d.txt"
    particles_cells_path = output_dir / "particles-cells.txt"
    particles_volumes_path = output_dir / "particles-volumes.txt"
    entity_sets_path = output_dir / "entity_sets.json"
    center_ids_path = output_dir / "core-center-ids.json"

    coordinates, cells = _read_mesh(mesh_path)
    _check_cells(coordinates, cells, tolerance)

    with particles_path.open("r", encoding="utf-8") as stream:
        nparticles = int(stream.readline().strip())
        particles = [
            tuple(float(value) for value in line.split())
            for line in stream
            if line.strip()
        ]
    if len(particles) != nparticles:
        _fail(f"particle count mismatch: expected {nparticles}, found {len(particles)}")

    particle_cells: dict[int, int] = {}
    with particles_cells_path.open("r", encoding="utf-8") as stream:
        for line in stream:
            if not line.strip():
                continue
            pid, cid = (int(value) for value in line.split())
            if pid in particle_cells:
                _fail(f"duplicate particle-to-cell entry for particle {pid}")
            if cid < 0 or cid >= len(cells):
                _fail(f"particle {pid} references invalid cell {cid}")
            particle_cells[pid] = cid
    if len(particle_cells) != nparticles:
        _fail("particle-to-cell file does not cover every particle")

    volume_ids: set[int] = set()
    with particles_volumes_path.open("r", encoding="utf-8") as stream:
        for line in stream:
            if not line.strip():
                continue
            pid, volume = (float(value) for value in line.split())
            integer_pid = int(pid)
            if integer_pid in volume_ids:
                _fail(f"duplicate particle volume for particle {integer_pid}")
            if volume <= 0.0 or not math.isfinite(volume):
                _fail(f"particle {integer_pid} has a non-positive volume")
            volume_ids.add(integer_pid)
    if volume_ids != set(particle_cells):
        _fail("particle volume IDs do not match particle-to-cell IDs")

    for pid, particle in enumerate(particles):
        cell = cells[particle_cells[pid]]
        x_values = [coordinates[node][0] for node in cell]
        y_values = [coordinates[node][1] for node in cell]
        z_values = [coordinates[node][2] for node in cell]
        if not (
            min(x_values) - tolerance <= particle[0] <= max(x_values) + tolerance
            and min(y_values) - tolerance <= particle[1] <= max(y_values) + tolerance
            and min(z_values) - tolerance <= particle[2] <= max(z_values) + tolerance
        ):
            _fail(f"particle {pid} lies outside its assigned cell")

    with entity_sets_path.open("r", encoding="utf-8") as stream:
        entity_sets = json.load(stream)
    for node_set in entity_sets.get("node_sets", []):
        if any(node < 0 or node >= len(coordinates) for node in node_set["set"]):
            _fail(f"node set {node_set['id']} references an invalid node")
    for particle_set in entity_sets.get("particle_sets", []):
        if any(pid < 0 or pid >= len(particles) for pid in particle_set["set"]):
            _fail(f"particle set {particle_set['id']} references an invalid particle")

    with center_ids_path.open("r", encoding="utf-8") as stream:
        center_ids = json.load(stream)
    node_id = int(center_ids["closest_node"]["id"])
    if node_id < 0 or node_id >= len(coordinates):
        _fail("core-center node ID is outside the node range")
    if center_ids["closest_particle"] is not None:
        particle_id = int(center_ids["closest_particle"]["id"])
        if particle_id < 0 or particle_id >= len(particles):
            _fail("core-center particle ID is outside the particle range")

    return {
        "nodes": len(coordinates),
        "cells": len(cells),
        "particles": len(particles),
    }


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Validate generated graded Hex8 MPM input files."
    )
    parser.add_argument(
        "output_dir",
        type=Path,
        help="directory containing the generated files",
    )
    parser.add_argument(
        "--tolerance",
        type=float,
        default=1.0e-8,
        help="geometric comparison tolerance",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    try:
        summary = validate(args.output_dir.resolve(), args.tolerance)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"validation failed: {error}", file=sys.stderr)
        return 1
    print(json.dumps(summary, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
